  // Core Applications
  codai: { port: 4030, name: 'CODAI Platform', category: 'Core' },
  memorai: { port: 4031, name: 'MEMORAI Core', category: 'Core' },
  bancai: { port: 4033, name: 'BANCAI Financial', category: 'Core' },
