// Health check function
async function checkHealth(service) {
  return new Promise((resolve) => {
    const req = http.request({
      hostname: 'localhost',
      port: service.port,
      path: '/',
      method: 'GET',
      timeout: 5000
    }, (res) => {
      resolve({
        service: service.name,
        port: service.port,
        category: service.category,
        status: 'HEALTHY',
        statusCode: res.statusCode,
        timestamp: new Date().toISOString()
      });
    });

    req.on('error', () => {
      resolve({
        service: service.name,
        port: service.port,
        category: service.category,
        status: 'UNHEALTHY',
        statusCode: null,
        timestamp: new Date().toISOString()
      });
    });

    req.on('timeout', () => {
      resolve({
        service: service.name,
        port: service.port,
        category: service.category,
        status: 'TIMEOUT',
        statusCode: null,
        timestamp: new Date().toISOString()
      });
    });

    req.end();
  });
}

// Main monitoring function
async function monitorEcosystem() {
  console.log('🚀 CODAI Ecosystem Health Monitor');
  console.log('=' .repeat(50));
  console.log(`Monitoring ${Object.keys(SERVICES).length} services...`);
  console.log(`Timestamp: ${new Date().toISOString()}`);
  console.log('');

  const results = await Promise.all(
    Object.values(SERVICES).map(service => checkHealth(service))
  );

  // Group by category
  const categories = {};
  results.forEach(result => {
    if (!categories[result.category]) {
      categories[result.category] = [];
    }
    categories[result.category].push(result);
  });

  // Display results by category
  Object.entries(categories).forEach(([category, services]) => {
    console.log(`📊 ${category} Services:`);
    console.log('-'.repeat(30));
    
    services.forEach(service => {
      const statusIcon = service.status === 'HEALTHY' ? '✅' : 
                        service.status === 'TIMEOUT' ? '⏰' : '❌';
      const statusText = service.status === 'HEALTHY' ? 
        `${service.status} (${service.statusCode})` : service.status;
      
      console.log(`${statusIcon} ${service.service.padEnd(25)} :${service.port} - ${statusText}`);
    });
    console.log('');
  });

  // Summary statistics
  const healthy = results.filter(r => r.status === 'HEALTHY').length;
  const total = results.length;
  const healthPercentage = ((healthy / total) * 100).toFixed(1);

  console.log('📈 Summary:');
  console.log('-'.repeat(30));
  console.log(`Total Services: ${total}`);
  console.log(`Healthy: ${healthy}`);
  console.log(`Unhealthy: ${total - healthy}`);
  console.log(`Health Percentage: ${healthPercentage}%`);
  
  // Overall status
  const overallStatus = healthPercentage >= 90 ? '🟢 EXCELLENT' :
                       healthPercentage >= 70 ? '🟡 GOOD' :
                       healthPercentage >= 50 ? '🟠 FAIR' : '🔴 POOR';
  
  console.log(`Overall Status: ${overallStatus}`);
  console.log('');

  // Export results as JSON for automation
  if (process.argv.includes('--json')) {
    console.log('JSON Results:');
    console.log(JSON.stringify({
      timestamp: new Date().toISOString(),
      total: total,
      healthy: healthy,
      healthPercentage: parseFloat(healthPercentage),
      services: results
    }, null, 2));
  }

  // Return health percentage for scripting
  process.exit(healthPercentage >= 90 ? 0 : 1);
}

// Command line options
if (process.argv.includes('--help')) {
  console.log(`
CODAI Ecosystem Health Monitor

Usage:
  node ecosystem-health-monitor.js          # Run health check
  node ecosystem-health-monitor.js --json   # Output JSON results
  node ecosystem-health-monitor.js --help   # Show this help

Exit codes:
  0 - Health >= 90% (excellent)
  1 - Health < 90% (needs attention)
  `);
  process.exit(0);
}

// Run monitoring
monitorEcosystem().catch(error => {
  console.error('❌ Monitoring failed:', error.message);
  process.exit(2);
});
